<?php
declare(strict_types=1);
namespace Hostider\Support\UI;
use Hostider\Core\{Validation,CanonicalJson};
use Hostider\Core\Http\HttpError;
use Hostider\Support\{Access,State};
use Hostider\Support\Advanced\Common;
use Hostider\Support\Work\{Eligibility,Time};
final readonly class Views
{
    public function __construct(private Context $x){}
    public static function filters(array $p,string $ctx,bool $page=true): array
    {
        $keys=['department_id','state'];if($page){$keys[]='offset';$keys[]='q';}if($ctx==='admin'){array_push($keys,'customer_id','assigned','risk');}Validation::fields($p,$keys,[]);if(array_key_exists('q',$p)){throw new HttpError(422,'SUPPORT_SEARCH_UNSUPPORTED');}foreach(['department_id','customer_id'] as $k){if(isset($p[$k])&&$p[$k]!==''){Access::id($p[$k]);}else{unset($p[$k]);}}$state=$p['state']??'open';if(!in_array($state,['all','open','waiting','NEW','WAITING_STAFF','WAITING_CUSTOMER','ON_HOLD','RESOLVED','CLOSED'],true)){throw new HttpError(422,'SUPPORT_FILTER_STATE');}$p['state']=$state;if(isset($p['assigned'])&&!in_array($p['assigned'],['all','mine','unassigned'],true)){throw new HttpError(422,'SUPPORT_FILTER_ASSIGNMENT');}if(isset($p['risk'])&&!in_array($p['risk'],['all','RISK','BREACH','UNAVAILABLE'],true)){throw new HttpError(422,'SUPPORT_FILTER_RISK');}if($page){Common::offset($p['offset']??'0');}return $p;
    }
    public function listing(string $ref,string $ctx,array $p): array
    {
        return $this->x->run($ref,$ctx,function($u,$s)use($ctx,$p){$p=self::filters($p,$ctx);$m=$this->x->m;$a=$m->access->actor($u,$s);[$where,$params]=$m->access->listing($a);foreach(['department_id','customer_id'] as $k){if(isset($p[$k])){$where.=' AND t.'.$k.'=?';$params[]=$p[$k];}}if($p['state']==='open'){$where.=" AND t.status NOT IN ('RESOLVED','CLOSED')";}elseif($p['state']==='waiting'){$where.=" AND t.status IN ('WAITING_STAFF','WAITING_CUSTOMER')";}elseif($p['state']!=='all'){$where.=' AND t.status=?';$params[]=$p['state'];}if(($p['assigned']??'all')==='mine'){$where.=' AND w.assignee_id=?';$params[]=$u['id'];}elseif(($p['assigned']??'all')==='unassigned'){$where.=' AND w.assignee_id IS NULL';}if(($p['risk']??'all')==='UNAVAILABLE'){$where.=" AND w.sla_status='UNAVAILABLE'";}elseif(in_array($p['risk']??null,['RISK','BREACH'],true)){$where.=' AND EXISTS(SELECT 1 FROM support_sla_clocks c JOIN support_sla_alerts a ON a.clock_id=c.id WHERE c.cycle_id=w.cycle_id AND a.level=?)';$params[]=$p['risk'];}$offset=Common::offset($p['offset']??'0');$rows=$m->c->db->execute('SELECT t.* FROM support_tickets t LEFT JOIN support_work_tickets w ON w.ticket_id=t.id WHERE '.$where.' ORDER BY t.id LIMIT 51 OFFSET '.$offset,$params)->fetchAll();$more=count($rows)>50;$out=[];foreach(array_slice($rows,0,50) as $t){$m->access->require($u,$s,$t['customer_id'],$t['department_id']);$out[]=$this->summary($t);}return ['items'=>$out,'has_more'=>$more,'offset'=>$offset,'limit'=>50,'scope_epoch'=>$this->x->epoch($u,$s),'search'=>'UNSUPPORTED'];});
    }
    private function summary(array $t): array{$r=array_intersect_key($t,array_flip(['id','number','customer_id','department_id','status','requested_priority','effective_priority','channel','created_at','updated_at']));$r['version']=(int)$t['version'];$r['subject']=$this->x->m->crypto->decrypt($t['subject_encrypted'],'support-subject:'.$t['id']);return $r;}
    public function detail(string $ref,string $ctx,array $p,bool $poll=false): array
    {
        Validation::fields($p,$poll?['id','snapshot','message_offset']:['id','message_offset'],['id']);Access::id($p['id']);$offset=Common::offset($p['message_offset']??'0');if(isset($p['snapshot'])&&(!is_string($p['snapshot'])||!preg_match('/^[a-f0-9]{64}$/D',$p['snapshot']))){throw new HttpError(422,'SUPPORT_SNAPSHOT_INVALID');}
        return $this->x->run($ref,$ctx,function($u,$s)use($p,$ctx,$poll,$offset){$m=$this->x->m;$db=$m->c->db;$t=$m->access->ticket($u,$s,$p['id']);$staff=$ctx==='admin';$notes=$staff&&$this->x->permission($u,$s,$t,'support.ticket.internal_note');$caps=[];foreach(['reply','manage','assign','internal_note'] as $perm){$caps[$perm]=($staff||$perm==='reply')&&$this->x->permission($u,$s,$t,'support.ticket.'.$perm);}$out=['ticket'=>$this->summary($t),'capabilities'=>$caps,'scope_epoch'=>$this->x->epoch($u,$s),'messages'=>[],'timeline'=>[],'incidents'=>[],'services'=>[],'message_offset'=>$offset,'message_limit'=>50,'transitions'=>[]];$rows=$db->execute('SELECT id,type,customer_visible,author_id,body_encrypted,created_at FROM support_messages WHERE ticket_id=? AND customer_id=?'.($notes?'':" AND customer_visible=TRUE AND type<>'internal_note'").' ORDER BY created_at DESC,id DESC LIMIT 51 OFFSET '.$offset,[$t['id'],$t['customer_id']])->fetchAll();$out['older_messages']=count($rows)>50;foreach(array_reverse(array_slice($rows,0,50)) as $row){$row['body']=$m->crypto->decrypt($row['body_encrypted'],'support-message:'.$row['id']);unset($row['body_encrypted']);$row['customer_visible']=(bool)$row['customer_visible'];$out['messages'][]=$row;}
            $kinds=$notes?['CREATED','CUSTOMER_REPLY','STAFF_REPLY','INTERNAL_NOTE','STATE','MOVE']:['CREATED','CUSTOMER_REPLY','STAFF_REPLY','STATE','MOVE'];$out['timeline']=$db->execute('SELECT kind,ticket_version,from_state,to_state,created_at FROM support_events WHERE ticket_id=? AND customer_id=? AND kind IN ('.implode(',',array_fill(0,count($kinds),'?')).') ORDER BY created_at DESC,id DESC LIMIT 20',[$t['id'],$t['customer_id'],...$kinds])->fetchAll();
            foreach($db->execute('SELECT service_id FROM support_ticket_links WHERE ticket_id=? AND customer_id=? LIMIT 10',[$t['id'],$t['customer_id']])->fetchAll() as $link){try{$out['services'][]=(new \Hostider\Services\SupportLinks($m->c))->owned($u,$s,$t['customer_id'],$link['service_id']);}catch(HttpError $e){if(!in_array($e->status,[403,404],true)){throw $e;}}}
            $customer=$m->c->identity->repository->customer($t['customer_id']);$out['customer']=['id'=>$customer['id'],'name'=>$customer['name']];$out['incidents']=$db->execute('SELECT i.id,i.status,i.version FROM support_incidents i JOIN support_incident_tickets l ON l.incident_id=i.id WHERE l.ticket_id=? AND l.customer_id=? AND i.department_id=? ORDER BY i.id LIMIT 20',[$t['id'],$t['customer_id'],$t['department_id']])->fetchAll();
            if($staff&&$caps['manage']){foreach(['NEW','WAITING_STAFF','WAITING_CUSTOMER','ON_HOLD','RESOLVED','CLOSED'] as $to){try{State::transition($t['status'],$to,$m->access->department($t['department_id']));$out['transitions'][]=$to;}catch(HttpError){}}}
            if(!$staff){$r=$db->execute('SELECT version,resolution_event FROM support_ratings WHERE ticket_id=? AND customer_id=?',[$t['id'],$t['customer_id']])->fetch();$policy=$db->execute('SELECT window_seconds FROM support_csat_policies WHERE department_id=?',[$t['department_id']])->fetch();$resolved=$db->execute("SELECT id,created_at FROM support_events WHERE ticket_id=? AND to_state='RESOLVED' AND (from_state IS NULL OR from_state<>'RESOLVED') ORDER BY ticket_version DESC LIMIT 1",[$t['id']])->fetch();$open=$t['status']==='RESOLVED'&&$policy&&$resolved&&Time::now($db)<Time::parse($resolved['created_at'])+(int)$policy['window_seconds']*1_000_000&&(!$r||$r['resolution_event']===$resolved['id']);$out['csat']=['eligible'=>(bool)$open,'version'=>(int)($r['version']??0),'reason'=>$open?'OPEN':($policy?'RESOLUTION_OR_WINDOW_UNAVAILABLE':'UNCONFIGURED')];}
            $out['snapshot']=$m->hash(['version'=>$t['version'],'epoch'=>$out['scope_epoch'],'offset'=>$offset,'incidents'=>$out['incidents'],'csat'=>$out['csat']??null]);if($poll&&isset($p['snapshot'])&&hash_equals($p['snapshot'],$out['snapshot'])){return ['changed'=>false,'version'=>(int)$t['version'],'scope_epoch'=>$out['scope_epoch'],'snapshot'=>$out['snapshot']];}return $out+['changed'=>true];});
    }
    public function operations(string $ref,string $view,array $p): array
    {
        Validation::fields($p,match($view){'rule'=>['id'],default=>['ticket_id']},$view==='rule'?['id']:['ticket_id']);return $this->x->run($ref,'admin',function($u,$s)use($view,$p){$m=$this->x->m;$db=$m->c->db;if($view==='rule'){$r=$db->execute('SELECT h.*,r.spec FROM support_rule_heads h JOIN support_rule_revisions r ON r.id=h.revision_id WHERE h.id=?',[Access::id($p['id'])])->fetch();if(!$r){throw new HttpError(404,'SUPPORT_NOT_FOUND');}$m->access->require($u,$s,$r['customer_id'],$r['department_id'],'support.automation.manage');$spec=json_decode($r['spec'],true,32,JSON_THROW_ON_ERROR);foreach($spec['actions'] as $a){$perm=match($a['kind']){'assign'=>'support.ticket.assign','note'=>'support.ticket.internal_note','incident'=>'support.incident.manage',default=>'support.ticket.manage'};$m->access->require($u,$s,$r['customer_id'],$r['department_id'],$perm);}return ['id'=>$r['id'],'version'=>(int)$r['version'],'spec'=>$spec];}
            $t=$m->access->ticket($u,$s,Access::id($p['ticket_id']));if($view==='eligible'){$m->access->require($u,$s,$t['customer_id'],$t['department_id'],'support.ticket.assign');$users=[];foreach((new Eligibility($m->c))->candidates($t,Time::now($db)) as $id){$person=$m->c->identity->repository->user($id);$users[]=['id'=>$id,'name'=>$person['display_name']];}return ['users'=>$users];}if($view==='settings'){$m->access->management($u,$s);$store=new \Hostider\Support\Work\Store($m->c);$head=$store->head($t['department_id']);$rows=$db->execute('SELECT h.user_id,h.version,r.spec FROM support_work_roster_heads h JOIN support_work_rosters r ON r.id=h.roster_id WHERE h.department_id=? ORDER BY h.user_id LIMIT 64',[$t['department_id']])->fetchAll();foreach($rows as &$r){$r['roster']=json_decode($r['spec'],true,32,JSON_THROW_ON_ERROR);unset($r['spec']);}unset($r);return ['head'=>$head,'policy'=>$store->policy($head['policy_id']),'rosters'=>$rows];}$m->access->require($u,$s,$t['customer_id'],$t['department_id'],'support.mail_review');(new \Hostider\Support\Mail\Common($m->c))->reviewer($u,$s,$t['department_id'],$t['customer_id']);return ['outbound'=>$db->execute('SELECT id,status,version,attempt_count FROM support_mail_outbound WHERE ticket_id=? AND customer_id=? ORDER BY id LIMIT 50',[$t['id'],$t['customer_id']])->fetchAll(),'delivery_confirmed'=>false];},true);
    }
}
